lam = {"A": 0, "B": 0, "C": 0, "D": 0}
s = {"A": 2.0, "B": 1.0, "C": 0.5, "D": 0.0}
pairs = [("B","A"), ("B","C"), ("B","D"),
         ("C","A"), ("C","D")]   # i more relevant
for i, j in pairs:
    rho = 1 / (1 + exp(s[i] - s[j]))  # sigma = 1
    lam[i] += rho                      # push i up
    lam[j] -= rho                      # push j down
